INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6509431, 967804, 61396, '<td valign="top">Great dog time, I think. The dynamic you created with a single stroke of your camera equipped hand makes me want to reverse the movement in an attempt to restore the original image this photo is a reminiscent of. I like this as an interpretation of the concept "time". The contrast, as the overall b/w conversion, is masterfully done.</td>', 'Great dog time, I think. The dynamic you created with a single stroke of your camera equipped hand makes me want to reverse the movement in an attempt to restore the original image this photo is a reminiscent of. I like this as an interpretation of the concept "time". The contrast, as the overall b/w conversion, is masterfully done.', '2011-08-19 11:51:01.000000', NULL, 1),
(6509451, 966745, 61396, '<td valign="top">I like that you try to sweeten the unpleasant notion (to us mortals) of time melting away using mostly cheerful colors.</td>', 'I like that you try to sweeten the unpleasant notion (to us mortals) of time melting away using mostly cheerful colors.', '2011-08-19 12:01:24.000000', NULL, 1),
(6509459, 967561, 61396, '<td valign="top">I like how the moving person casting orange glow and the static twelve sections floor mosaic half hidden in dirt both represent time in such different ways.</td>', 'I like how the moving person casting orange glow and the static twelve sections floor mosaic half hidden in dirt both represent time in such different ways.', '2011-08-19 12:11:36.000000', NULL, 1),
(6509469, 967034, 108580, '<td valign="top">Super silhouette work and relevant to the challenge spirit. But is it getting hammered cos it''s not a pic of a clock? Bah Humbug if it is!<br/>I love it...Three strong elements and scale reference to tell the time as any hiker or "out there" type should be able to. Due the mist I''d say it was morning and about 7:30-8:00am? Hehe.</td>', 'Super silhouette work and relevant to the challenge spirit. But is it getting hammered cos it''s not a pic of a clock? Bah Humbug if it is!I love it...Three strong elements and scale reference to tell the time as any hiker or "out there" type should be able to. Due the mist I''d say it was morning and about 7:30-8:00am? Hehe.', '2011-08-19 12:13:19.000000', NULL, 1),
