(6518363, 967778, 87278, '<td valign="top">Grand composition! A life time compressed in a capsule.<br/>Congrats on the ribbon!</td>', 'Grand composition! A life time compressed in a capsule.Congrats on the ribbon!', '2011-08-28 07:29:15.000000', NULL, 0),
(6518368, 967579, 87278, '<td valign="top">Brilliant! And congrats!<br/> <br/>I am not a photographer and do not know the technical stuff at all. I just drop in here now and then to pay my respect to all you experts and enthusiasts alike.<br/> <br/>Thanks for all the details of how you got this shot. It is a lesson in innovation and professionalism.<br/> <br/>I am amazed at the troubles you all take to get a complex idea (as time) translated into a visual picture! The inversion, to my mind, adds drama and takes your work out of teh ordinary or predictable.</td>', 'Brilliant! And congrats! I am not a photographer and do not know the technical stuff at all. I just drop in here now and then to pay my respect to all you experts and enthusiasts alike. Thanks for all the details of how you got this shot. It is a lesson in innovation and professionalism. I am amazed at the troubles you all take to get a complex idea (as time) translated into a visual picture! The inversion, to my mind, adds drama and takes your work out of teh ordinary or predictable.', '2011-08-28 07:42:26.000000', NULL, 0),
(6518397, 967275, 100335, '<td valign="top">I loved this image, and i thought it would do better. Quite surprised to see it placing 36! Winner in my book.</td>', 'I loved this image, and i thought it would do better. Quite surprised to see it placing 36! Winner in my book.', '2011-08-28 09:01:19.000000', NULL, 0),
(6519513, 967692, 109387, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by thawby:</b></div><hr/><i> I would be very interested in the initial lighting versus the the red light capture.  Well done! </i></td></tr></table> <br/> <br/>All the light is given by a videocamera led lamp. I crawled around the cups and in the end I gave a little light from above. The room was mostly dark. The cup were over a black panel.</td>', 'Originally posted by thawby: I would be very interested in the initial lighting versus the the red light capture.  Well done!   All the light is given by a videocamera led lamp. I crawled around the cups and in the end I gave a little light from above. The room was mostly dark. The cup were over a black panel.', '2011-08-29 12:30:09.000000', NULL, 0),
(6519685, 967778, 137320, '<td valign="top">Love the story you tell here. Art at it''s best here!</td>', 'Love the story you tell here. Art at it''s best here!', '2011-08-29 15:26:38.000000', NULL, 0),
(6520226, 967275, 114285, '<td valign="top">Like what <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=10785" rel="nofollow" target="_blank">EL-ROI </a> said, robbery.</td>', 'Like what  EL-ROI  said, robbery.', '2011-08-29 22:53:24.000000', NULL, 0),
