(6544429, 967767, 23484, '<td valign="top">Great contrast.</td>', 'Great contrast.', '2011-09-18 22:59:32.000000', NULL, 0),
(6620727, 967804, 30982, '<td valign="top">Like.</td>', 'Like.', '2011-12-18 12:02:33.000000', NULL, 0),
(6940344, 967778, 152252, '<td valign="top">I thought I commented on it before. I love your three present faces + the past. Good composition.<br/>Well deserved ribbon!<br/><br/><i>Message edited by author 2012-12-22 23:37:52.</i></td>', 'I thought I commented on it before. I love your three present faces + the past. Good composition.Well deserved ribbon!', '2012-12-22 23:37:29.000000', '2012-12-22 23:37:52.000000', 0),
(6940759, 967778, 5112, '<td valign="top">Ahh, yes.  Where did time go.  Having just turned 60, this is very much the way I sometimes feel.  However, I really like the older face better :)  It shows a lot of life.  I like that.</td>', 'Ahh, yes.  Where did time go.  Having just turned 60, this is very much the way I sometimes feel.  However, I really like the older face better :)  It shows a lot of life.  I like that.', '2012-12-23 14:47:15.000000', NULL, 0),
(6940850, 967778, 109227, '<td valign="top">This is one of my favorites; great job in setting this up.  You have aged very well, lol.</td>', 'This is one of my favorites; great job in setting this up.  You have aged very well, lol.', '2012-12-23 18:01:54.000000', NULL, 0);
